window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"lvl0nQMAZ9I","speaker":"William Samoei Ruto","role":"President","country":"Kenya","region":"Africa","url":"https://www.youtube.com/watch?v=lvl0nQMAZ9I","date":"20260923","title":"🇰🇪 Kenya - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1924,"words":2971,"counts":{"claims":48,"promises":2,"attacks":0},"topics":[{"topic":"UN reform","share":0.1777,"seconds":342},{"topic":"UN Security Council reform","share":0.0991,"seconds":191},{"topic":"UN Security Council","share":0.0721,"seconds":139},{"topic":"African debt","share":0.0707,"seconds":136},{"topic":"African finance","share":0.0694,"seconds":134},{"topic":"UN peacekeeping","share":0.0676,"seconds":130},{"topic":"Global finance","share":0.0656,"seconds":126},{"topic":"Kenya education debt","share":0.0434,"seconds":84},{"topic":"Global South representation","share":0.0403,"seconds":78},{"topic":"Decolonization","share":0.036,"seconds":69},{"topic":"International law","share":0.0359,"seconds":69},{"topic":"Kenya energy","share":0.0343,"seconds":66},{"topic":"Kenya independence","share":0.0341,"seconds":66},{"topic":"Global violence","share":0.0339,"seconds":65},{"topic":"African resources","share":0.0333,"seconds":64},{"topic":"Global debt","share":0.0327,"seconds":63},{"topic":"African representation","share":0.0323,"seconds":62},{"topic":"Multilateralism","share":0.0215,"seconds":41}],"timeline":[[2,71,"UN reform"],[73,139,"Kenya independence"],[141,210,"Decolonization"],[213,282,"UN peacekeeping"],[284,346,"UN reform"],[346,412,"Global violence"],[414,475,"UN peacekeeping"],[478,545,"UN Security Council"],[547,618,"UN Security Council"],[621,690,"International law"],[694,756,"African representation"],[758,820,"UN Security Council reform"],[822,885,"Global debt"],[887,971,"Kenya education debt"],[973,1035,"Global finance"],[1037,1105,"African finance"],[1107,1172,"Global finance"],[1174,1236,"African debt"],[1237,1301,"African resources"],[1303,1369,"Kenya energy"],[1370,1435,"African finance"],[1438,1512,"African debt"],[1514,1576,"UN Security Council reform"],[1578,1644,"UN Security Council reform"],[1647,1714,"UN reform"],[1716,1793,"Global South representation"],[1795,1864,"UN reform"],[1866,1941,"UN reform"],[1942,1984,"Multilateralism"]],"stances":{"UN reform":"William Samoei Ruto references the historical context of the UN's founding in San Francisco 81 years ago to highlight its original resolutions on peace and human dignity.","Kenya independence":"William Samoei Ruto states that Kenya joined the UN with full sovereign rights and equal standing to other nations.","Decolonization":"William Samoei Ruto states that decolonization transformed the world map by replacing colonial subjugation with self-determination and highlights the UN's role in supporting specific nations' independence.","UN peacekeeping":"William Samoei Ruto asserts that the United Nations has successfully built, protected, and sustained peace while eradicating diseases and improving global living standards.","Global violence":"William Samoei Ruto states that organized violence, interstate conflicts, and one-sided violence against civilians have increased significantly, causing widespread destruction and suffering.","UN Security Council":"William Samoei Ruto argues that the current UN structure creates inequality by granting permanent power to five nations while all others have equal sovereignty.","International law":"William Samoei Ruto argues that international law must be applied consistently without double standards to maintain trust and prevent human suffering.","African representation":"William Samoei Ruto argues that the current global security architecture was designed without African input due to colonial rule, creating a contradiction where young Africans inherit the consequences of failed institutions.","UN Security Council reform":"William Samoei Ruto argues that the UN Security Council and international financial institutions must transform to ensure equality and fair economic opportunities for all nations.","Global debt":"William Samoei Ruto states that developing countries are paying excessive interest on their public debt, which consumes resources needed for essential services like education and healthcare.","Kenya education debt":"William Samoei Ruto argues that prioritizing debt service over education harms the next generation and states that Kenya has chosen to invest in education instead.","Global finance":"William Samoei Ruto argues that the international financial system imposes disproportionately high borrowing costs on developing nations, hindering their development.","African finance":"William Samoei Ruto argues that subjective sovereign credit ratings impose excessive financial costs on African nations and hinder the creation of a fair global economy.","African debt":"William Samoei Ruto argues that African nations must manage their own debt and strengthen institutions while calling for a fairer international system.","African resources":"William Samoei Ruto argues that Africa's natural assets should be developed into local industry to address global challenges rather than being merely extracted.","Kenya energy":"William Samoei Ruto states that Kenya intends to participate in the African continental free trade area by breaking ground on a new East African refinery.","Global South representation":"William Samoei Ruto calls for a world where international law is applied equally regardless of state identity and where developing nations have greater representation in global decision-making.","Multilateralism":"William Samoei Ruto expresses Kenya's belief in the United Nations and readiness to build multilateralism, while thanking the audience for their attention."},"claims":[{"t":44,"quote":"81 years ago, the nations gathered in San Francisco spoke from the ruins of war.","topic":"UN reform","kind":"fact"},{"t":54,"quote":"They resolved to save succeeding generations from its scouch. They reaffirmed faith in human dignity and in the equal rights of nations large and small.","topic":"UN reform","kind":"fact"},{"t":112,"quote":"On 16th December 1963, four days after our independence, Kenya took its seat in this assembly.","topic":"Kenya independence","kind":"fact"},{"t":125,"quote":"We arrived with one vote and the same sovereign rights as every other state.","topic":"Kenya independence","kind":"fact"},{"t":144,"quote":"When the United Nations was founded, some 750 million people lived under colonial At San Francisco, only four African countries were represented while most of our continent remained under colonial rule.","topic":"Decolonization","kind":"number"},{"t":192,"quote":"It helped Namibia achieve independence, supported Cambodia's transition from conflict, disarmed combatants in Sierra Leon and Liberia, and helped Timo Leel take its place among sovereign nations.","topic":"Decolonization","kind":"fact"},{"t":213,"quote":"More than two million peacekeepers have served under the UN flag","topic":"UN peacekeeping","kind":"number"},{"t":251,"quote":"Since the year 2000, deaths among children under five have fallen by more than half","topic":"UN peacekeeping","kind":"number"},{"t":327,"quote":"last year the world recorded 65 statebased armed conflicts, the highest number of documented incidences in eight digits of global conflict data. 13 reached the scale of war.","topic":"UN reform","kind":"number"},{"t":346,"quote":"Nearly a quarter of a million people were killed in organized violence.","topic":"Global violence","kind":"number"},{"t":353,"quote":"Interstate conflicts doubled for the second consecutive year.","topic":"Global violence","kind":"fact"},{"t":359,"quote":"Their number quadrupled from 2 to 8.","topic":"Global violence","kind":"number"},{"t":365,"quote":"One-sided violence against civilians reached levels not witnessed since 1994, the year of genocide in Rwanda.","topic":"Global violence","kind":"fact"},{"t":414,"quote":"Too many disputes are no longer being settled. They are being frozen, or decided by force.","topic":"UN peacekeeping","kind":"fact"},{"t":433,"quote":"It did not ask the United Nations merely to describe war or count victims or organize relief after diplomacy has","topic":"UN peacekeeping","kind":"fact"},{"t":522,"quote":"Every nation in this hall has one vote. Every nation is sovereign and equal under the charter.","topic":"UN Security Council","kind":"fact"},{"t":531,"quote":"Yet on the gravest question of war and five nations possess a permanent power that the other 188 do not.","topic":"UN Security Council","kind":"fact"},{"t":570,"quote":"Africa has 54 member states, more than a quarter of this assembly, yet no permanent voice in the body entrusted with the primary responsibility of international peace and security.","topic":"UN Security Council","kind":"fact"},{"t":662,"quote":"It is measured in children driven from their classrooms. Children who go to sleep hungry, children who learn the sound of gunfire before they know the safety of peace.","topic":"International law","kind":"fact"},{"t":678,"quote":"When collective security breaks down, schools close, hospitals collapse, families flee, and economies are consumed by war.","topic":"International law","kind":"fact"},{"t":722,"quote":"In 1945, most of our continent could not speak for itself as San Francisco because it remained under colonial rule. Only four African states were","topic":"African representation","kind":"fact"},{"t":806,"quote":"The charter did not conceive development as charity. It pledged social progress, better standards of life, and economic and social advancement for all people.","topic":"UN Security Council reform","kind":"fact"},{"t":834,"quote":"Global public debt reached a record $12 trillion in 2024.","topic":"Global debt","kind":"number"},{"t":843,"quote":"Developing countries accounted for less than a third of that debt, yet paid about a trillion dollar in interest on debt in that year alone.","topic":"Global debt","kind":"number"},{"t":861,"quote":"46 developing countries now spend more on interest on debt than on classrooms and medicine.","topic":"Global debt","kind":"number"},{"t":904,"quote":"Today, million children and young people remain out of school. Millions more enter classrooms without teachers, books, meals, and facilities they need to","topic":"Kenya education debt","kind":"fact"},{"t":946,"quote":"Over the last four years, we have spent an additional $5.3 billion in education, recruited 100,000 additional teachers, build more than 23,000 new classrooms, and we are developing another 1,600 laboratories while expanding support for universities and technical institutions.","topic":"Kenya education debt","kind":"self_credit"},{"t":1010,"quote":"Developing countries have recently borrowed at rates two to four times higher on average than developed nations.","topic":"Global finance","kind":"number"},{"t":1057,"quote":"UNDP estimates that subjectivities in credit ratings have cost African countries approximately $75 billion through excessive interest and forgone Risk","topic":"African finance","kind":"number"},{"t":1137,"quote":"The UN charter envisaged multilateral development banks that lend more, lend longer, and mobilize private capital at It further contemplated guarantees and risk sharing instruments that reduce the cost of viable investments.","topic":"Global finance","kind":"fact"},{"t":1184,"quote":"must also do their part to manage debt prudently, strengthen institutions, prepare pipelines of credible projects, deepen domestic capital markets, honor contracts, and confront corruption without A fairer international system requires responsibility on both sides.","topic":"African debt","kind":"fact"},{"t":1233,"quote":"Our continent holds fast mineral wealth.","topic":"African debt","kind":"fact"},{"t":1247,"quote":"We are a market of more than 1.5 billion people increasingly connected through the African continental free trade area.","topic":"African resources","kind":"number"},{"t":1343,"quote":"In the next one week, we expect to break ground on the East African refinery in A refinery capable of producing 700,000 barrels of oils of oil a day. An investment of approximately $16 billion.","topic":"Kenya energy","kind":"number"},{"t":1395,"quote":"including the more than $4 trillion in domestic capital across pension funds, insurance assets, sovereign wealth funds, banks, and other institutions in","topic":"African finance","kind":"number"},{"t":1438,"quote":"Africa's 54 nations are home to nearly one in every five people on Earth.","topic":"African debt","kind":"number"},{"t":1444,"quote":"Yet our influence on the institutions that govern global finance remain disproportionately small.","topic":"African debt","kind":"fact"},{"t":1554,"quote":"In 2008, after years of discussion, this general assembly moved security council reform into intergovernmental negotiations.","topic":"UN Security Council reform","kind":"fact"},{"t":1564,"quote":"Those negotiations began the following year. 17 years later, we are still The central question remain before us.","topic":"UN Security Council reform","kind":"number"},{"t":1622,"quote":"In 1963, this general assembly adopted amendments to enlarge the security council. The council grew from 11 members to 15 because member states recognized that the institution had to respond to a changing membership.","topic":"UN Security Council reform","kind":"fact"},{"t":1694,"quote":"More than half a century ago, this general assembly called for a new international economic order founded on sovereign equality, interdependence, and cooperation among states.","topic":"UN reform","kind":"fact"},{"t":1750,"quote":"It requires that no child lose a classroom because debt service came fast. That no mother finds an empty clinic because essential investment became unaffordable.","topic":"Global South representation","kind":"fact"},{"t":1782,"quote":"Africa recognizes your steadfast advocacy for a fairer international financial architecture, greater African representation, and a stronger voice for the global south.","topic":"Global South representation","kind":"self_credit"},{"t":1820,"quote":"81 years ago, the founders of this organization looked upon a broken world and chose not to preserve the order that had failed them.","topic":"UN reform","kind":"fact"},{"t":1837,"quote":"We must not wait for another catastrophe to reform this institution whose weaknesses we can already see.","topic":"UN reform","kind":"fact"},{"t":1866,"quote":"If we are serious about restoring trust, and I'm sure we are, then rules must apply consistently.","topic":"UN reform","kind":"fact"},{"t":1889,"quote":"If we seek a united nations that delivers for all then all must have a meaningful voice a fair opportunity and a stake in the Let ours be the generation that completes the unfinished work of San","topic":"UN reform","kind":"fact"},{"t":1942,"quote":"That is the United Nations Kenya believes in. That is multilateralism Africa is ready to build.","topic":"Multilateralism","kind":"fact"}],"promises":[{"t":1343,"quote":"In the next one week, we expect to break ground on the East African refinery","topic":"Kenya energy","kind":"promise"},{"t":1392,"quote":"And that is what we intend to do, including the more than $4 trillion in domestic capital across pension funds, insurance assets, sovereign wealth funds, banks, and other institutions in The task is to mobilize more of that capital for productive investment while building the safeguards, credible projects and financial instruments that long-term investors require.","topic":"African finance","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UN reform","text":"and the assembly will hear an address by his excellency William Samoi Ruto, president of the Republic of Kenya and the commander-in-chief of defense I request protocol to escort his excellency and invite him to address the Mr. President of the General Assembly, Mr. Secretary General, excellencies, ladies and gentlemen, 81 years ago, the nations gathered in San Francisco spoke from the ruins of war. They resolved to save succeeding generations from its scouch. They reaffirmed faith in human dignity and in the equal rights of nations large and small."},{"t":73,"topic":"Kenya independence","text":"and they pledged social progress, better standards of life and the economic and social advancement of all peoples. These were not mere words. They were the foundations of a new global order. Peace over war, law over force, sovereign equality over dependency, over division, and human dignity over ambitions of power. On 16th December 1963, four days after our independence, Kenya took its seat in this assembly. We arrived with one vote and the same sovereign rights as every other state. The promise made in San Francisco now belonged to us as well."},{"t":141,"topic":"Decolonization","text":"And that promise changed the world. When the United Nations was founded, some 750 million people lived under colonial At San Francisco, only four African countries were represented while most of our continent remained under colonial rule. Decolonization transformed the map of the world, replacing colonial subjugation with self-determination. As peoples once governed from afar took their place in this assembly as sovereign equals. The United Nations also made a difference where peace had been broken. It helped Namibia achieve independence, supported Cambodia's transition from conflict, disarmed combatants in Sierra Leon and Liberia, and helped Timo Leel take its place among sovereign nations."},{"t":213,"topic":"UN peacekeeping","text":"More than two million peacekeepers have served under the UN flag, proving that peace can be built, protected, and sustained. Its impact reached further into the lives of ordinary people. The United Nations system helped eradicate small pox, vaccinated generations of children, fight hunger and disease, expand access to education, and bring clean water and humanitarian assistance to communities across the world. Since the year 2000, deaths among children under five have fallen by more than half. These achievements matter. They changed borders, ended wars, defeated disease, and transformed lives. They tell us that multilateralism works when nations summon the will to make it work."},{"t":284,"topic":"UN reform","text":"The United Nations has not fulfilled every promise of its charter. But without it, our world would have been poorer, more dangerous, and less free. That is why Kenya speaks today, not from despair in this institution, but from conviction in its Yet conviction in what this institution can be requires us to confront what this institution has become. Distinguished delegates, last year the world recorded 65 statebased armed conflicts, the highest number of documented incidences in eight digits of global conflict data. 13 reached the scale of war."},{"t":346,"topic":"Global violence","text":"Nearly a quarter of a million people were killed in organized violence. Interstate conflicts doubled for the second consecutive year. Their number quadrupled from 2 to 8. One-sided violence against civilians reached levels not witnessed since 1994, the year of genocide in Rwanda. From Europe to the Middle East, from Sahel to the Horn of Africa, civilians are paying the ultimate price. Cities are destroyed. Families are displaced. Hunger deepens. Supply chains are disrupted, driving up the cost of food, fuel, and essential goods far beyond the Children inherit wars they did not begin and cannot understand."},{"t":414,"topic":"UN peacekeeping","text":"Too many disputes are no longer being settled. They are being frozen, or decided by force. This is precisely what the charter was created to prevent. It did not ask the United Nations merely to describe war or count victims or organize relief after diplomacy has It gave this organization, the United Nations, a duty to prevent conflict, defend peace, and make collective security real. It also charged it to advance the economic and social well-being of all Peace and prosperity were never two They were one promise."},{"t":478,"topic":"UN Security Council","text":"Today both sides of that promise are under strain. The crisis of multilateralism is not a shortage of commitments, institutions or rules. It is the widening distance between the equality this system proclaims and the inequality that is inherent in its structures. That is precisely why we cannot accept its present limitations on peace and security. The contradiction is increasingly difficult to ignore. Every nation in this hall has one vote. Every nation is sovereign and equal under the charter. Yet on the gravest question of war and five nations possess a permanent power that the other 188 do not."},{"t":547,"topic":"UN Security Council","text":"The equality proclaimed in this assembly ends at the doors of the security That imbalance might have reflected the world of 1945. It does not reflect the world that we know today. Africa has 54 member states, more than a quarter of this assembly, yet no permanent voice in the body entrusted with the primary responsibility of international peace and security. We are we are frequently the subject of its Permanently discussed yet permanently The problem is not that the world lacks It is that confidence in its consistent application is weakening."},{"t":621,"topic":"International law","text":"International law cannot be invoked loudly in one crisis, cautiously in another crisis and disregarded when convenient. Every perceived double standard carries a price and that price is trust. Trust cannot be restored by declaration. It must be earned by consistent application. But the cost of failure is measured in more than lost trust. It is measured in children driven from their classrooms. Children who go to sleep hungry, children who learn the sound of gunfire before they know the safety of peace. When collective security breaks down, schools close, hospitals collapse, families flee, and economies are consumed by war."},{"t":694,"topic":"African representation","text":"Peace is not separate from development. It is its first condition. When the institutions entrusted with peace fail, it is too often the youngest who inherit the consequences. exposes this contradiction most clearly. In 1945, most of our continent could not speak for itself as San Francisco because it remained under colonial rule. Only four African states were The architecture of collective security was therefore designed at a moment when most Africans had neither a nation at the table nor a voice in shaping the institutions that it would govern the The world, ladies and gentlemen, has since transformed."},{"t":758,"topic":"UN Security Council reform","text":"The council, the security council has not. We cannot manage transformation with institutions that refuse to transform The test of equality does not end with the institutions that govern peace. It extends to the institutions that shape prosperity. The same question confronts us there. Does the international financial system give every nation a fair opportunity to secure the well-being of its citizens. The charter did not conceive development as charity. It pledged social progress, better standards of life, and economic and social advancement for all people."},{"t":822,"topic":"Global debt","text":"Yet for too many countries, the resources required to fulfill that promise are being consumed before they can reach their people. Global public debt reached a record $12 trillion in 2024. Developing countries accounted for less than a third of that debt, yet paid about a trillion dollar in interest on debt in that year alone. Put it differently, 46 developing countries now spend more on interest on debt than on classrooms and medicine. Behind these numbers lies a simple The hospital competes with a creditor."},{"t":887,"topic":"Kenya education debt","text":"The classroom competes with debt And too often the creditor debt service is paid first. And it is our children who inherit the consequences. Today, million children and young people remain out of school. Millions more enter classrooms without teachers, books, meals, and facilities they need to When debt service displaces investment in education, we are not merely balancing budgets. We are transferring the cost of today's financial burden to the next generation of citizens. Kenya has chosen to invest in the next generation. Over the last four years, we have spent an additional $5.3 billion in education, recruited 100,000 additional teachers, build more than 23,000 new classrooms, and we are developing another 1,600 laboratories while expanding support for universities and technical institutions."},{"t":973,"topic":"Global finance","text":"We do this because education is not consumption. It is the infrastructure of opportunity, productivity and national transformation that supports global advancement. But national effort can only go so far when the international financial system makes development more expensive. The countries that most need capital frequently pay the highest price to obtain it. Developing countries have recently borrowed at rates two to four times higher on average than developed nations. The question therefore is available. It is who can access it, at what price, for how long, and under whose assessment of risk."},{"t":1037,"topic":"African finance","text":"Africa knows the cost of that Sovereign created rating shapes perceptions of risk, the interest countries pay, and even the volume of finance available to them. UNDP estimates that subjectivities in credit ratings have cost African countries approximately $75 billion through excessive interest and forgone Risk, ladies and gentlemen, must be measured, but it must also be measured We cannot build a fair global economy if the nations with the greatest development needs face the highest cost of development finance. A road that is commercially viable should not become unviable merely because it crosses an African border."},{"t":1107,"topic":"Global finance","text":"A power project should not cost more simply because of the passport of the it is building. Capital must price risk. It must not price prejudice. Reform of the international financial architecture must therefore begin with a cost and availability of capital. The UN charter envisaged multilateral development banks that lend more, lend longer, and mobilize private capital at It further contemplated guarantees and risk sharing instruments that reduce the cost of viable investments. And we need greater access to long-term and local currency finance so that countries are not forced to build long-term infrastructure with short-term expensive money."},{"t":1174,"topic":"African debt","text":"And by the way, this is not an argument against responsibility. must also do their part to manage debt prudently, strengthen institutions, prepare pipelines of credible projects, deepen domestic capital markets, honor contracts, and confront corruption without A fairer international system requires responsibility on both sides. Reform abroad cannot substitute for accountability at home. Distinguished delegates, Africa does not come to plead. We come with a proposal. Our continent holds fast mineral wealth."},{"t":1237,"topic":"African resources","text":"immense agricultural potential, extraordinary renewable energy resources, and the world's youngest We are a market of more than 1.5 billion people increasingly connected through the African continental free trade area. These are not merely African assets. properly developed, they are part of the answer to the world's search for food security, clean energy, resilient supply chains, and a new source of growth. Africa's resources must become the beginning of African industry, not the end of Africa's contribution to the value chain. Extraction defined too much of our past. Investment must underpin our future. This transition is already taking shape."},{"t":1303,"topic":"Kenya energy","text":"Cocoa producing nations are moving from bean to brand. Cotton producers are building government value chains. And Africa has made its position clear. The clean energy transition must not become another extractive transition. The Africa continental free trade area must be more than a market for what Africa already produces. It must become the platform on which Africa makes more of what it now imports. Kenya intends to be part of that In the next one week, we expect to break ground on the East African refinery in A refinery capable of producing 700,000 barrels of oils of oil a day. An investment of approximately $16 billion. Its significance extends beyond one project or one country."},{"t":1370,"topic":"African finance","text":"It represents the Africa we seek to build. Adding value at home, creating jobs for our people, and building industries capable of serving continents and global That transformation should be financed using foreign and domestic resources. And that is what we intend to do, including the more than $4 trillion in domestic capital across pension funds, insurance assets, sovereign wealth funds, banks, and other institutions in The task is to mobilize more of that capital for productive investment while building the safeguards, credible projects and financial instruments that long-term investors require. The imbalance is not only about money, it is also about voice."},{"t":1438,"topic":"African debt","text":"Africa's 54 nations are home to nearly one in every five people on Earth. Yet our influence on the institutions that govern global finance remain disproportionately small. We cannot carry substantial obligations under a system while remaining marginal in shaping its rules. If Africa has a stake in the burden of debt, Africa must have a share in the decisions on how that debt is acquired. This is not a plea for special It is a proposition for shared A more industrialized Africa expands global demand. A more food secure Africa strengthens global stability. A better connected Africa diversifies global supply chains and an Africa able to finance more of its own development becomes a stronger partner for the this brings us back to the central question before this assembly."},{"t":1514,"topic":"UN Security Council reform","text":"Whether in the security council or in the international financial system, institutions built for another age are being asked to govern a completely different world that we live in today. Restoring trust requires more than defending those institutions. It requires having the courage to reform This is not a conversation we are beginning today. For decades, member states have debated how to make the security council more representative, legitimate, and effective. In 2008, after years of discussion, this general assembly moved security council reform into intergovernmental negotiations. Those negotiations began the following year. 17 years later, we are still The central question remain before us."},{"t":1578,"topic":"UN Security Council reform","text":"Membership, the veto, regional representation, the size and working methods of the security council and its relationship with this general assembly. The world has not stood still while we have been debating these issues. In the pact for the future, member states agreed that redressing the historical injustice against Africa must be a priority in the security council We should not accept that reform is impossible because it is difficult. This organization has changed its architecture before. In 1963, this general assembly adopted amendments to enlarge the security council. The council grew from 11 members to 15 because member states recognized that the institution had to respond to a changing membership."},{"t":1647,"topic":"UN reform","text":"What was possible then, ladies and gentlemen, is possible today. Reform must deliver equitable and permanent representation with all the prerogatives and privileges of permanent membership to Africa and other deserving regions. Political reform and financial reform are not separate projects. They ask the same fundamental question. Whether the institutions that govern our common future will reflect the sovereign equality they proclaim or preserve inequalities inherited from another age. More than half a century ago, this general assembly called for a new international economic order founded on sovereign equality, interdependence, and cooperation among states. We need not recreate the debates of another era, but we must ask the question they left unfinished."},{"t":1716,"topic":"Global South representation","text":"What does equality among nations require in the world of today? It requires a world in which no continent is permanently excluded from the highest decisions on peace and A world in which international law does not change with the identity of the state to which it is applied. A world in which a nation's prospects are not determined by how expensive the world has decided its capital to be. It requires that no child lose a classroom because debt service came fast. That no mother finds an empty clinic because essential investment became unaffordable. And that the resources of developing countries became foundations for their prosperity rather than pathways for Mr. Secretary General, as you approach the conclusion of your stewardship of this great organization, Africa recognizes your steadfast advocacy for a fairer international financial architecture, greater African representation, and a stronger voice for the global south."},{"t":1795,"topic":"UN reform","text":"You have reminded the world that dignity, equality, and representation are not favors, but principles to be And perhaps the greatest tribute to your stewardship will be to turn the reforms you championed into reality. Distinguished delegates, 81 years ago, the founders of this organization looked upon a broken world and chose not to preserve the order that had failed them. They built a new order. Our responsibility is no less consequential today. We must not wait for another catastrophe to reform this institution whose weaknesses we can already see. We must not ask our children to inherit wars that we can prevent or debts that we can make sustainable, inequalities we can correct, and institutions we know no longer reflect the world we live in."},{"t":1866,"topic":"UN reform","text":"If we are serious about restoring trust, and I'm sure we are, then rules must apply consistently. If we are serious about managing transformation as it is and as has been then our institutions must themselves reform and transform. And if we seek a united nations that delivers for all then all must have a meaningful voice a fair opportunity and a stake in the Let ours be the generation that completes the unfinished work of San That makes sovereign equality real in our institutions, makes international law consistent in its application, makes capital serve development, and makes cooperation stronger than division. Not a United Nations of some nations, not a system in which power determines whose voice matter, but a United Nations worthy of its name, where every nation has a voice, every people have a stake, and every child has a future."},{"t":1942,"topic":"Multilateralism","text":"That is the United Nations Kenya believes in. That is multilateralism Africa is ready to build. And that is the promise of our that we must keep. I thank you for your attention. Thank you very much. On behalf of the assembly, I wish to thank the president of the Republic of Kenya and commanderin-chief of the defense forces. It's not simply whether finance"}],"compare":[{"topic":"UN & its reform","share":0.4164,"mean":0.2036,"rank":14,"others":170},{"topic":"Africa","share":0.2058,"mean":0.0225,"rank":5,"others":36},{"topic":"Global Economy","share":0.1387,"mean":0.0139,"rank":5,"others":31},{"topic":"International Law & Order","share":0.0933,"mean":0.0602,"rank":48,"others":102},{"topic":"Terrorism","share":0.0339,"mean":0.0027,"rank":7,"others":6}]};
